// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Every Java program stores information in variables. Let's meet the three primitive types you'll use on the AP exam.","blocks":[{"t":"p","text":"A variable is a named box that holds a value. In Java you must declare its type before using it."},{"t":"list","items":["int holds whole numbers: int score = 95;","double holds decimals: double price = 4.99;","boolean holds true or false: boolean done = false;"]},{"t":"code","text":"int age = 16;\ndouble gpa = 3.8;\nboolean hasPermit = true;\nage = age + 1;   // age is now 17"},{"t":"p","text":"A variable declared final can't change after it's set: final int MAX = 100;"},{"t":"oops","text":"= means \"store into,\" not \"is equal to.\" age = age + 1 takes the old value, adds 1, and stores it back."}]},{"say":"Java does math a little differently than your calculator, especially with whole numbers. This trips up a lot of people!","blocks":[{"t":"key","text":"When both operands are int, / does integer division and drops the remainder. % gives the remainder."},{"t":"code","text":"System.out.println(17 / 5);   // 3\nSystem.out.println(17 % 5);   // 2\nSystem.out.println(17.0 / 5); // 3.4"},{"t":"p","text":"Java follows order of operations: *, / and % happen before + and −, left to right. Compound assignment operators are shortcuts: x += 3 means x = x + 3. x++ adds 1."},{"t":"ex","problem":"What does 7 + 10 / 4 * 2 evaluate to?","steps":["10 / 4 = 2 (integer division)","2 * 2 = 4","7 + 4 = 11"],"answer":"11"},{"t":"tip","text":"n % 2 == 0 tests whether n is even. n % 10 gives the last digit of n."}]},{"say":"Sometimes you need to turn a double into an int, or the other way around. That's called casting.","blocks":[{"t":"p","text":"Casting converts a value to another type: (int) 3.99 is 3 because casting to int truncates (chops off) the decimal. (double) 7 is 7.0."},{"t":"ex","problem":"int a = 7, b = 2. What does (double) a / b give?","steps":["The cast happens first: (double) a is 7.0","7.0 / 2 uses double division"],"answer":"3.5"},{"t":"p","text":"To round a positive double to the nearest int, use (int) (x + 0.5)."},{"t":"p","text":"An int is stored in 32 bits, so it ranges from Integer.MIN_VALUE (−2,147,483,648) to Integer.MAX_VALUE (2,147,483,647). Going past the limit causes overflow: the value wraps around."},{"t":"oops","text":"(double) (7 / 2) is 3.0, not 3.5. The integer division inside the parentheses happens before the cast."}]},{"say":"Objects are the heart of Java. A class is the blueprint, and an object is the thing you build from it.","blocks":[{"t":"p","text":"A class defines what an object knows (its attributes) and can do (its methods). You create an object with new, which calls a constructor."},{"t":"code","text":"Scanner input = new Scanner(System.in);\nString name = new String(\"Ada\");\nTurtle t = new Turtle(world);"},{"t":"p","text":"The variable holds a reference to the object, not the object itself. A reference variable that doesn't point to any object holds null, and calling a method on null throws a NullPointerException."},{"t":"p","text":"Call a method with dot notation: object.method(arguments). Methods can be void (just do something) or return a value you can store or print. Static methods belong to the class, so you call them on the class name, like Math.sqrt(16)."}]},{"say":"Strings are objects that hold text, and they come with handy methods. Let's learn the ones on the AP Java Quick Reference.","blocks":[{"t":"p","text":"Strings are indexed from 0. In \"CODE\", C is at index 0 and E is at index 3. The length is 4."},{"t":"list","items":["length() returns the number of characters.","substring(a, b) returns characters from index a up to but NOT including b.","substring(a) returns from index a to the end.","indexOf(str) returns the first index where str appears, or −1 if it's not there.","equals(other) checks if two strings have the same characters.","compareTo(other) returns a negative number, 0 or a positive number for alphabetical order."]},{"t":"ex","problem":"String s = \"lumino\"; What is s.substring(1, 4)?","steps":["Index 1 is u, index 2 is m, index 3 is i","Stop before index 4"],"answer":"\"umi\""},{"t":"oops","text":"Use equals to compare Strings, not ==. The == operator checks whether two references point to the same object."},{"t":"tip","text":"Strings are immutable: methods like substring return a new String and never change the original."}]},{"say":"Java's Math class has ready-made tools for powers, roots and random numbers. All its methods are static.","blocks":[{"t":"list","items":["Math.abs(x): absolute value","Math.pow(base, exp): returns a double","Math.sqrt(x): returns a double","Math.random(): a double from 0.0 up to (but not including) 1.0"]},{"t":"key","text":"To get a random int from min to max inclusive: (int) (Math.random() * (max − min + 1)) + min"},{"t":"ex","problem":"Write an expression for a random die roll from 1 to 6","steps":["Range size: 6 − 1 + 1 = 6","Math.random() * 6 gives 0.0 up to 5.999…","Cast to int: 0 to 5, then add 1"],"answer":"(int) (Math.random() * 6) + 1"},{"t":"p","text":"Wrapper classes Integer and Double let primitives act like objects (needed for ArrayList). Java converts automatically: this is called autoboxing and unboxing."}]}],[{"say":"Programs make decisions with if statements. They run code only when a condition is true.","blocks":[{"t":"p","text":"Relational operators compare values and produce a boolean: ==, !=, <, >, <=, >=."},{"t":"code","text":"if (score >= 90) {\n    grade = \"A\";\n} else if (score >= 80) {\n    grade = \"B\";\n} else {\n    grade = \"C or below\";\n}"},{"t":"p","text":"In an if / else if / else chain, Java checks conditions top to bottom and runs only the first branch that is true."},{"t":"oops","text":"Order matters. If you check score >= 80 before score >= 90, a 95 gets a B, because the first true branch wins."}]},{"say":"You can combine conditions with and, or, and not. Java is clever about skipping work, too.","blocks":[{"t":"list","items":["&& (and): true only if both sides are true.","|| (or): true if at least one side is true.","! (not): flips true and false."]},{"t":"p","text":"Short-circuit evaluation: with &&, if the left side is false, Java skips the right side. With ||, if the left side is true, it skips the right side. This lets you write safe checks like if (obj != null && obj.isReady())."},{"t":"key","text":"De Morgan's laws: !(a && b) is the same as !a || !b, and !(a || b) is the same as !a && !b."},{"t":"ex","problem":"Simplify !(x > 3 && y == 0)","steps":["Apply De Morgan: !(x > 3) || !(y == 0)","Flip each comparison"],"answer":"x <= 3 || y != 0"}]},{"say":"Loops let your program repeat. A while loop keeps going as long as its condition is true.","blocks":[{"t":"code","text":"int n = 1;\nwhile (n < 100) {\n    n = n * 2;\n}\nSystem.out.println(n);   // 128"},{"t":"p","text":"Every loop needs three things: start (initialize), a condition to check, and an update that eventually makes the condition false. Without the update you get an infinite loop."},{"t":"ex","problem":"How many times does the body run? int k = 10; while (k > 0) { k -= 3; }","steps":["k goes 10 → 7 → 4 → 1 → −2","The body ran for k = 10, 7, 4 and 1"],"answer":"4 times"},{"t":"tip","text":"Trace loops with a table: write each variable's value at the end of every pass."}]},{"say":"A for loop packs the start, condition and update into one line. It's perfect for counting.","blocks":[{"t":"code","text":"for (int i = 0; i < 5; i++) {\n    System.out.print(i + \" \");\n}\n// prints 0 1 2 3 4"},{"t":"p","text":"A loop that runs from 0 while i < n runs exactly n times. Off-by-one errors happen when you use <= instead of < (or start at 1 instead of 0)."},{"t":"p","text":"Nested loops put one loop inside another. The inner loop runs completely for each pass of the outer loop."},{"t":"ex","problem":"How many times is \"*\" printed? for (int r = 0; r < 3; r++) for (int c = 0; c < 4; c++) print(\"*\");","steps":["The inner loop runs 4 times per outer pass","The outer loop runs 3 times"],"answer":"3 × 4 = 12 times"}]},{"say":"Combining loops and String methods lets you search, count and reverse text. These show up on every AP exam.","blocks":[{"t":"p","text":"Loop through a String with an index from 0 to length() − 1 and grab one character at a time with substring(i, i + 1)."},{"t":"code","text":"String word = \"mississippi\";\nint count = 0;\nfor (int i = 0; i < word.length(); i++) {\n    if (word.substring(i, i + 1).equals(\"s\")) {\n        count++;\n    }\n}\n// count is 4"},{"t":"p","text":"Common String algorithms: count a letter, find if a substring exists, reverse a String, check for a palindrome, and remove characters."},{"t":"ex","problem":"Build the reverse of \"code\"","steps":["Start with rev = \"\"","Loop i from 0 up: rev = word.substring(i, i + 1) + rev","c → oc → doc → edoc"],"answer":"\"edoc\""},{"t":"oops","text":"Looping with i <= word.length() goes one past the end and throws a StringIndexOutOfBoundsException."}]}],[{"say":"Now you get to design your own objects! Let's look at the parts of a class.","blocks":[{"t":"code","text":"public class Student {\n    private String name;   // instance variables\n    private int grade;\n\n    public Student(String n, int g) {   // constructor\n        name = n;\n        grade = g;\n    }\n\n    public String getName() { return name; }   // accessor\n}"},{"t":"p","text":"Instance variables store each object's data. They should be private so other classes can't change them directly. This is called encapsulation."},{"t":"p","text":"Methods are usually public so other classes can use them. A class's private data is reached only through its public methods."}]},{"say":"Constructors set up a new object, accessors read its data, and mutators change it. Let's write all three.","blocks":[{"t":"p","text":"A constructor has the same name as the class and no return type. A class can have several constructors with different parameters (overloading). If you write none, Java gives a default constructor that sets numbers to 0, booleans to false and objects to null."},{"t":"code","text":"public class BankAccount {\n    private double balance;\n    public BankAccount(double start) { balance = start; }\n    public double getBalance() { return balance; }            // accessor\n    public void deposit(double amt) { balance += amt; }       // mutator\n}"},{"t":"p","text":"An accessor (getter) returns a value and doesn't change the object. A mutator (setter) changes instance variables and is usually void."},{"t":"p","text":"A method's signature is its name and parameter list. A return statement sends a value back and ends the method immediately."},{"t":"oops","text":"Writing void before a constructor's name makes it a regular method, not a constructor!"}]},{"say":"Some variables belong to the whole class instead of one object. And Java has rules about where each variable lives.","blocks":[{"t":"p","text":"A static variable is shared by every object of the class, like a counter of how many objects have been made. A static method can't use instance variables because it doesn't belong to any one object."},{"t":"code","text":"public class Ticket {\n    private static int sold = 0;\n    private int number;\n    public Ticket() { sold++; number = sold; }\n}"},{"t":"p","text":"The keyword this refers to the current object. It's often used when a parameter has the same name as an instance variable: this.name = name;"},{"t":"p","text":"Scope is where a variable can be used. Local variables (declared inside a method or loop) exist only inside that block. Parameters are local to their method."},{"t":"oops","text":"If a parameter is named the same as an instance variable and you write name = name;, nothing changes. Use this.name = name;"}]},{"say":"Good programmers write code other people can understand, and think about how their code affects people.","blocks":[{"t":"p","text":"Comments explain code: // for one line, /* */ for several lines, and /** */ for Javadoc. Javadoc comments describe what a method does, its parameters (@param) and what it returns (@return)."},{"t":"p","text":"Preconditions are what must be true before a method is called. Postconditions are what will be true after it runs. The AP exam uses them to tell you what you can assume."},{"t":"p","text":"Computing has real effects on people. Programs can protect or leak personal data, and algorithms can be unfair if they're built on biased data. Programmers should respect privacy, licenses and intellectual property."}]}],[{"say":"An array holds many values of the same type in one variable. It's like a row of numbered lockers.","blocks":[{"t":"code","text":"int[] scores = new int[5];          // five 0s\ndouble[] prices = {1.99, 4.50, 3.25};\nscores[0] = 90;\nSystem.out.println(prices.length);  // 3"},{"t":"p","text":"Arrays have a fixed length set when they're created. Indexes run from 0 to length − 1. New int arrays are filled with 0, doubles with 0.0, booleans with false and object references with null."},{"t":"p","text":"Traverse an array with a for loop or an enhanced for loop. The enhanced for loop is simpler but can't change the array's elements or tell you the index."},{"t":"code","text":"int sum = 0;\nfor (int s : scores) { sum += s; }"},{"t":"oops","text":"Using an index of length or more (or a negative index) throws an ArrayIndexOutOfBoundsException."}]},{"say":"Most array problems use the same few patterns. Learn these and you can solve almost any free-response question.","blocks":[{"t":"p","text":"Standard algorithms:"},{"t":"list","items":["Sum or average all elements.","Find the maximum or minimum.","Count elements that meet a condition.","Check if any or all elements have a property.","Shift or rotate elements, or reverse the array."]},{"t":"ex","problem":"Find the largest value in int[] a","steps":["Start with max = a[0]","Loop through the rest: if (a[i] > max) max = a[i];","After the loop, max holds the largest value"],"answer":"max = a[0], then update it whenever a bigger value appears"},{"t":"oops","text":"Starting max at 0 breaks when every value is negative. Start with the first element instead."}]},{"say":"An ArrayList is like an array that can grow and shrink. It's perfect when you don't know how many items you'll have.","blocks":[{"t":"code","text":"ArrayList<String> names = new ArrayList<String>();\nnames.add(\"Ana\");          // [Ana]\nnames.add(\"Ben\");          // [Ana, Ben]\nnames.add(1, \"Cal\");       // [Ana, Cal, Ben]\nnames.set(0, \"Abe\");       // [Abe, Cal, Ben]\nnames.remove(1);           // [Abe, Ben]\nSystem.out.println(names.size());   // 2"},{"t":"p","text":"An ArrayList holds objects, so for numbers use wrapper types: ArrayList<Integer>. Use size() instead of length, and get(i) instead of [i]."},{"t":"key","text":"When you remove items while looping forward, the next item slides into the current index. Loop backward, or don't increase i after a removal."}]},{"say":"A 2D array is a grid of rows and columns, like a spreadsheet or a game board.","blocks":[{"t":"code","text":"int[][] grid = new int[3][4];   // 3 rows, 4 columns\ngrid[1][2] = 7;                 // row 1, column 2\nint rows = grid.length;         // 3\nint cols = grid[0].length;      // 4"},{"t":"p","text":"Java stores a 2D array as an array of rows. Row-major traversal goes across each row, top to bottom. Column-major goes down each column, left to right."},{"t":"code","text":"for (int r = 0; r < grid.length; r++) {\n    for (int c = 0; c < grid[0].length; c++) {\n        System.out.print(grid[r][c] + \" \");\n    }\n}"},{"t":"tip","text":"Always write the row first: grid[row][col]. A quick way to remember: \"RC, like RC car.\""}]},{"say":"Finding and ordering data are two classic problems. Let's compare the algorithms you need to know.","blocks":[{"t":"p","text":"Linear search checks each element in order until it finds the target. It works on any list. Binary search only works on sorted data: it checks the middle, then throws away the half that can't contain the target. It's much faster on large lists."},{"t":"list","items":["Selection sort: find the smallest remaining element and swap it into the next position.","Insertion sort: take the next element and slide it left into its place among the sorted part.","Merge sort: split the list in half, sort each half recursively, then merge them. It's the fastest of the three on large lists."]},{"t":"ex","problem":"Binary search for 23 in [3, 8, 15, 23, 42, 57, 71]","steps":["Middle is index 3: 23. Found it!"],"answer":"Found at index 3 after 1 check"},{"t":"tip","text":"Binary search on a list of 1,000 items needs at most about 10 checks, because 2¹⁰ = 1,024."}]},{"say":"A recursive method calls itself! It solves a big problem by solving a smaller version of the same problem.","blocks":[{"t":"p","text":"Every recursive method needs a base case that stops the recursion, and a recursive call that moves toward the base case."},{"t":"code","text":"public static int factorial(int n) {\n    if (n == 0) return 1;            // base case\n    return n * factorial(n - 1);     // recursive call\n}"},{"t":"ex","problem":"Trace factorial(4)","steps":["factorial(4) = 4 * factorial(3)","factorial(3) = 3 * factorial(2)","factorial(2) = 2 * factorial(1) and factorial(1) = 1 * factorial(0) = 1","Multiply back up: 2, then 6, then 24"],"answer":"24"},{"t":"oops","text":"A recursive method with no base case (or one it never reaches) keeps calling itself until the program crashes with a StackOverflowError."}]},{"say":"Real programs work with real data. Let's read a file and analyze a data set, which is new to the AP exam.","blocks":[{"t":"p","text":"Java can read a text file with the File and Scanner classes. Reading a file can throw an IOException, so the method header declares throws IOException."},{"t":"code","text":"import java.io.*;\nimport java.util.*;\npublic static int countLines(String path) throws IOException {\n    Scanner in = new Scanner(new File(path));\n    int count = 0;\n    while (in.hasNextLine()) {\n        String line = in.nextLine();\n        count++;\n    }\n    in.close();\n    return count;\n}"},{"t":"p","text":"A common pattern: read each line, use split(\",\") to break it into fields, convert numbers with Integer.parseInt or Double.parseDouble, and store objects in an ArrayList. Then use array and list algorithms to find totals, averages, maximums and patterns."},{"t":"p","text":"Data sets can be incomplete or biased. Before trusting a conclusion, ask how the data was collected and who might be missing from it."}]}]];
export default text;
